    // Example 2 - Demonstrates the LED test where PWM commands are sent to LEDs and PWM response is captured at TestPoint via analog buffer to validate Dutycycle
    await sendAndValidatePwmAnalogBuffer(); // Send and Validate PWM(Analog Buffer)
  } finally {
    await turnOffAllAoChannels(); // Turn Off all AO Channels
  }
}

